// Sound: sounds are loaded once, and every time one is played it gets a channel, which can then be changed or stopped.
// Everything is mixed by SDL3_mixer, which decodes WAV, MP3, OGG and FLAC.
//
// Without a sound device (or with BLITZ_HEADLESS set) all of this still works, it just stays silent.

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <SDL3/SDL.h>
#include <SDL3_mixer/SDL_mixer.h>

extern void bb_runtime_error(const char* message);
extern int  bb_entity_world_matrix(int32_t handle, float* matrix);

typedef struct bb_sound {
	MIX_Audio* audio;
	int        frequency; // Of the file, for pitch changes.
	int        used;
	int        loop;
	float      volume;
	float      pan;
	int        pitch; // In Hz, 0 for what the file has.
	int        is_3d;
} bb_sound;

typedef struct bb_channel {
	MIX_Track* track;
	int        used;
	int        sound;
	int32_t    entity; // For sounds that come from somewhere in the world, 0 otherwise.
	float      volume;
	float      pan;
	int        frequency;
} bb_channel;

static MIX_Mixer*  bb_mixer       = NULL;
static int         bb_audio_tried = 0;
static bb_sound*   bb_sounds      = NULL;
static int32_t     bb_sound_count = 1;
static int32_t     bb_sound_cap   = 0;
static bb_channel* bb_channels    = NULL;
static int32_t     bb_channel_count = 1;
static int32_t     bb_channel_cap = 0;

// The listener, who 3D sounds are heard from.
static int32_t bb_listener_entity = 0;
static float   bb_listener_rolloff = 1.0f;

// Starts the sound system the first time it is needed. Returns whether there is something to play on.
static int bb_audio_ready(void)
{
	if (bb_audio_tried) {
		return bb_mixer != NULL;
	}
	bb_audio_tried = 1;
	if (getenv("BLITZ_HEADLESS")) {
		return 0;
	}
	if (!SDL_InitSubSystem(SDL_INIT_AUDIO) || !MIX_Init()) {
		return 0;
	}
	bb_mixer = MIX_CreateMixerDevice(SDL_AUDIO_DEVICE_DEFAULT_PLAYBACK, NULL);
	return bb_mixer != NULL;
}

static float bb_clamp(float v, float lo, float hi)
{
	return v < lo ? lo : (v > hi ? hi : v);
}

static bb_sound* bb_sound_get(int32_t handle, const char* what)
{
	static bb_sound none; // Programs pass the 0 of a sound that failed to load, which Blitz ignores.
	if (handle == 0) {
		memset(&none, 0, sizeof(none));
		return &none;
	}
	if ((handle < 0) || (handle >= bb_sound_count) || !bb_sounds[handle].used) {
		char message[96];
		snprintf(message, sizeof(message), "%s: the sound does not exist.", what);
		bb_runtime_error(message);
	}
	return &bb_sounds[handle];
}

static bb_channel* bb_channel_get(int32_t handle)
{
	if ((handle <= 0) || (handle >= bb_channel_count) || !bb_channels[handle].used) {
		return NULL; // Channels end by themselves, programs can still hold on to them.
	}
	return &bb_channels[handle];
}

static int32_t bb_load(const char* path, int is_3d)
{
	if (!path) {
		return 0;
	}
	char* real = (char*)malloc(strlen(path) + 1);
	strcpy(real, path);
#if !defined(_WIN32)
	for (char* c = real; *c; c++) {
		if (*c == '\\') {
			*c = '/';
		}
	}
#endif

	bb_sound sound;
	memset(&sound, 0, sizeof(sound));
	sound.used   = 1;
	sound.volume = 1.0f;
	sound.is_3d  = is_3d;

	if (bb_audio_ready()) {
		sound.audio = MIX_LoadAudio(bb_mixer, real, true);
		if (!sound.audio) {
			free(real);
			return 0; // Missing or unusable files give 0, like in Blitz.
		}
		SDL_AudioSpec spec;
		if (MIX_GetAudioFormat(sound.audio, &spec)) {
			sound.frequency = spec.freq;
		}
	} else {
		// No sound device: just remember that the file is there.
		FILE* file = fopen(real, "rb");
		if (!file) {
			free(real);
			return 0;
		}
		fclose(file);
	}
	free(real);

	for (int32_t i = 1; i < bb_sound_count; i++) {
		if (!bb_sounds[i].used) {
			bb_sounds[i] = sound;
			return i;
		}
	}
	if (bb_sound_count >= bb_sound_cap) {
		bb_sound_cap = bb_sound_cap ? bb_sound_cap * 2 : 64;
		bb_sounds    = (bb_sound*)realloc(bb_sounds, (size_t)bb_sound_cap * sizeof(bb_sound));
	}
	bb_sounds[bb_sound_count] = sound;
	return bb_sound_count++;
}

int32_t bb_load_sound(const char* path)
{
	return bb_load(path, 0);
}

int32_t bb_load_3d_sound(const char* path)
{
	return bb_load(path, 1);
}

void bb_free_sound(int32_t handle)
{
	bb_sound* sound = bb_sound_get(handle, "FreeSound");
	for (int32_t i = 1; i < bb_channel_count; i++) {
		if (bb_channels[i].used && (bb_channels[i].sound == handle)) {
			MIX_DestroyTrack(bb_channels[i].track);
			memset(&bb_channels[i], 0, sizeof(bb_channel));
		}
	}
	if (sound->audio) {
		MIX_DestroyAudio(sound->audio);
	}
	memset(sound, 0, sizeof(*sound));
}

void bb_loop_sound(int32_t handle)
{
	bb_sound_get(handle, "LoopSound")->loop = 1;
}

void bb_sound_volume(int32_t handle, float volume)
{
	bb_sound_get(handle, "SoundVolume")->volume = bb_clamp(volume, 0.0f, 1.0f);
}

void bb_sound_pan(int32_t handle, float pan)
{
	bb_sound_get(handle, "SoundPan")->pan = bb_clamp(pan, -1.0f, 1.0f);
}

void bb_sound_pitch(int32_t handle, int32_t hertz)
{
	bb_sound_get(handle, "SoundPitch")->pitch = hertz;
}

// Sets the track to what the channel says. Gains are 0 to 1, and the pan from left (-1) to right (1).
static void bb_channel_apply(bb_channel* channel, float volume, float pan)
{
	MIX_SetTrackGain(channel->track, bb_clamp(volume, 0.0f, 1.0f));
	MIX_StereoGains gains;
	gains.left  = pan > 0 ? 1.0f - pan : 1.0f;
	gains.right = pan < 0 ? 1.0f + pan : 1.0f;
	MIX_SetTrackStereo(channel->track, &gains);
}

static int32_t bb_play(int32_t handle, int32_t entity, const char* what)
{
	bb_sound* sound = bb_sound_get(handle, what);
	if (!bb_mixer || !sound->audio) {
		return 0;
	}

	// Reuse the slot of a channel that is over.
	int32_t slot = 0;
	for (int32_t i = 1; i < bb_channel_count; i++) {
		if (bb_channels[i].used && !MIX_TrackPlaying(bb_channels[i].track) && !MIX_TrackPaused(bb_channels[i].track)) {
			MIX_DestroyTrack(bb_channels[i].track);
			memset(&bb_channels[i], 0, sizeof(bb_channel));
		}
		if (!slot && !bb_channels[i].used) {
			slot = i;
		}
	}
	if (!slot) {
		if (bb_channel_count >= bb_channel_cap) {
			bb_channel_cap = bb_channel_cap ? bb_channel_cap * 2 : 64;
			bb_channels    = (bb_channel*)realloc(bb_channels, (size_t)bb_channel_cap * sizeof(bb_channel));
		}
		slot = bb_channel_count++;
	}

	bb_channel* channel = &bb_channels[slot];
	memset(channel, 0, sizeof(*channel));
	channel->track = MIX_CreateTrack(bb_mixer);
	if (!channel->track) {
		return 0;
	}
	channel->used      = 1;
	channel->sound     = handle;
	channel->entity    = entity;
	channel->volume    = sound->volume;
	channel->pan       = sound->pan;
	channel->frequency = sound->pitch;

	MIX_SetTrackAudio(channel->track, sound->audio);
	MIX_SetTrackLoops(channel->track, sound->loop ? -1 : 0);
	if (sound->pitch > 0 && sound->frequency > 0) {
		MIX_SetTrackFrequencyRatio(channel->track, (float)sound->pitch / (float)sound->frequency);
	}
	bb_channel_apply(channel, channel->volume, channel->pan);
	MIX_PlayTrack(channel->track, 0);
	return slot;
}

int32_t bb_play_sound(int32_t handle)
{
	return bb_play(handle, 0, "PlaySound");
}

int32_t bb_emit_sound(int32_t handle, int32_t entity)
{
	return bb_play(handle, entity, "EmitSound");
}

void bb_stop_channel(int32_t handle)
{
	bb_channel* channel = bb_channel_get(handle);
	if (channel) {
		MIX_StopTrack(channel->track, 0);
		MIX_DestroyTrack(channel->track);
		memset(channel, 0, sizeof(*channel));
	}
}

void bb_pause_channel(int32_t handle)
{
	bb_channel* channel = bb_channel_get(handle);
	if (channel) {
		MIX_PauseTrack(channel->track);
	}
}

void bb_resume_channel(int32_t handle)
{
	bb_channel* channel = bb_channel_get(handle);
	if (channel) {
		MIX_ResumeTrack(channel->track);
	}
}

int32_t bb_channel_playing(int32_t handle)
{
	bb_channel* channel = bb_channel_get(handle);
	return (channel && (MIX_TrackPlaying(channel->track) || MIX_TrackPaused(channel->track))) ? 1 : 0;
}

void bb_channel_volume(int32_t handle, float volume)
{
	bb_channel* channel = bb_channel_get(handle);
	if (channel) {
		channel->volume = bb_clamp(volume, 0.0f, 1.0f);
		bb_channel_apply(channel, channel->volume, channel->pan);
	}
}

void bb_channel_pan(int32_t handle, float pan)
{
	bb_channel* channel = bb_channel_get(handle);
	if (channel) {
		channel->pan = bb_clamp(pan, -1.0f, 1.0f);
		bb_channel_apply(channel, channel->volume, channel->pan);
	}
}

void bb_channel_pitch(int32_t handle, int32_t hertz)
{
	bb_channel* channel = bb_channel_get(handle);
	if (channel && (hertz > 0)) {
		bb_sound* sound = &bb_sounds[channel->sound];
		if (sound->frequency > 0) {
			MIX_SetTrackFrequencyRatio(channel->track, (float)hertz / (float)sound->frequency);
		}
	}
}

////////////////////////////////////////////////////////////////////////////////
// 3D
////////////////////////////////////////////////////////////////////////////////
int32_t bb_create_listener(int32_t entity, float rolloff, float doppler, float distance)
{
	(void)doppler;  // Not simulated.
	(void)distance; // Distances are always in the units of the world.
	bb_listener_entity  = entity;
	bb_listener_rolloff = rolloff;
	return 1;
}

// Sounds that come from an entity get quieter with distance, and move between the speakers.
void bb_sound_update(void)
{
	if (!bb_mixer || !bb_listener_entity) {
		return;
	}
	float listener[16];
	if (!bb_entity_world_matrix(bb_listener_entity, listener)) {
		return;
	}
	for (int32_t i = 1; i < bb_channel_count; i++) {
		bb_channel* channel = &bb_channels[i];
		if (!channel->used || !channel->entity) {
			continue;
		}
		float source[16];
		if (!bb_entity_world_matrix(channel->entity, source)) {
			continue;
		}
		float dx = source[12] - listener[12], dy = source[13] - listener[13], dz = source[14] - listener[14];
		float distance = sqrtf(dx * dx + dy * dy + dz * dz);
		float gain     = 1.0f / (1.0f + bb_listener_rolloff * distance * 0.05f);
		// The listener's right is the first column of its matrix.
		float rx = listener[0], ry = listener[1], rz = listener[2];
		float rl = sqrtf(rx * rx + ry * ry + rz * rz);
		float pan = 0.0f;
		if ((distance > 1e-3f) && (rl > 1e-6f)) {
			pan = (dx * rx + dy * ry + dz * rz) / (distance * rl);
		}
		bb_channel_apply(channel, channel->volume * gain, bb_clamp(channel->pan + pan, -1.0f, 1.0f));
	}
}
